import { NAME_MAX, type PartySettings, type PartySlug, type PlayerView, type RoomBrand, type RoomPublic } from "@play4fun/party";
import type { RunningGame } from "./games/types";

/**
 * Two ids per player:
 * - `secret`: generated by the browser and kept in its localStorage. Only the server ever sees
 *   it; presenting it again (reload, phone woke up) gives the seat back.
 * - `id`: public, random, made by the server. This is what everyone in the room sees (player
 *   list, votes, roles at the end), so knowing it does not let anyone take the seat.
 */
export type Player = {
  id: string;
  secret: string;
  name: string;
  /** null while disconnected */
  socketId: string | null;
  joinedAt: number;
  /** When the player disconnected (for the reconnect grace period) */
  leftAt: number | null;
};

export type Room = {
  code: string;
  gameSlug: PartySlug;
  hostId: string;
  players: Map<string, Player>;
  status: "lobby" | "playing";
  settings: PartySettings;
  createdAt: number;
  game: RunningGame | null;
  timers: Map<string, NodeJS.Timeout>;
  /** Content ids already used in this room (word pairs, words, questions) to avoid repeats */
  used: Set<string>;
  /** Studio question set chosen by the host (Đố vui team building) */
  custom: CustomSet | null;
  /** Who created the room (per-IP room limit) */
  creatorIp?: string;
};

export type CustomSet = { id: string; title: string; brand: RoomBrand; questions: { q: string; options: string[]; correct: number }[] };

const CODE_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // bỏ O/0/I/1 cho dễ đọc
const CODE_LENGTH = 5;

/**
 * Room state lives in RAM: enough for a single realtime instance.
 * To scale out, move it to Valkey and use the socket.io redis adapter.
 */
export const rooms = new Map<string, Room>();

export function newRoomCode(): string {
  for (;;) {
    let code = "";
    for (let i = 0; i < CODE_LENGTH; i++) code += CODE_ALPHABET[Math.floor(Math.random() * CODE_ALPHABET.length)];
    if (!rooms.has(code)) return code;
  }
}

export function cleanName(raw: unknown): string | null {
  if (typeof raw !== "string") return null;
  const name = raw.normalize("NFC").trim().replace(/\s+/g, " ").slice(0, NAME_MAX);
  return name.length > 0 ? name : null;
}

/** Public player id: random, never derived from the client secret */
export function newPlayerId(room: Room): string {
  for (;;) {
    const id = `p${Math.random().toString(36).slice(2, 12)}`;
    if (!room.players.has(id)) return id;
  }
}

export const playerBySecret = (room: Room, secret: string) => [...room.players.values()].find((p) => p.secret === secret);

/** Client secrets are random UUID-ish strings; reject anything else */
export function cleanPid(raw: unknown): string | null {
  return typeof raw === "string" && /^[A-Za-z0-9_-]{8,64}$/.test(raw) ? raw : null;
}

export function cleanCode(raw: unknown): string {
  return typeof raw === "string" ? raw.trim().toUpperCase().slice(0, CODE_LENGTH) : "";
}

/** Players in join order */
export const playerList = (room: Room) => [...room.players.values()].sort((a, b) => a.joinedAt - b.joinedAt);

export const connectedIds = (room: Room) => playerList(room).filter((p) => p.socketId).map((p) => p.id);

export function publicRoom(room: Room): RoomPublic {
  return {
    code: room.code,
    gameSlug: room.gameSlug,
    hostId: room.hostId,
    status: room.status,
    settings: room.settings,
    brand: room.custom?.brand ?? null,
    customSet: room.custom ? { id: room.custom.id, title: room.custom.title, count: room.custom.questions.length } : null,
    players: playerList(room).map((p): PlayerView => ({ id: p.id, name: p.name, connected: p.socketId !== null })),
  };
}

/** Make the earliest connected player host if the current host is gone */
export function ensureHost(room: Room) {
  const host = room.players.get(room.hostId);
  if (host?.socketId) return;
  const next = playerList(room).find((p) => p.socketId);
  if (next) room.hostId = next.id;
  else if (!host) {
    const any = playerList(room)[0];
    if (any) room.hostId = any.id;
  }
}

export function clearTimers(room: Room) {
  for (const t of room.timers.values()) clearTimeout(t);
  room.timers.clear();
}
